    r->m[1]=y[0];
    r->m[2]=z[0];
    r->m[4]=x[1];
    r->m[5]=y[1];
    r->m[6]=z[1];
    r->m[8]=x[2];
    r->m[9]=y[2];
    r->m[10]=z[2];
    r->m[12]=-(x[0]*eye[0]+x[1]*eye[1]+x[2]*eye[2]);
    r->m[13]=-(y[0]*eye[0]+y[1]*eye[1]+y[2]*eye[2]);
